}

try {
  failProcess("Connection reset by peer");
} catch (e: any) {
  console.log("Handled never-returning function:", e.message);
}
FULL_CODE_END -->

# Function Type Signatures 📋

Define reusable function signatures using type aliases:

```typescript
// Define the type contract for a math operation function
type MathOperation = (a: number, b: number) => number;

const add: MathOperation = (x, y) => x + y;
const multiply: MathOperation = (x, y) => x * y;

console.log("Add 10+5:", add(10, 5));
console.log("Multiply 10*5:", multiply(10, 5));
```

