# Exhaustive Checks with `never` 🛡️

Use `never` to ensure that every case in a `switch` statement is handled:

```typescript
type Shape = "Circle" | "Square" | "Triangle";

function getPerimeterFormula(shape: Shape): string {
  switch (shape) {
    case "Circle":
      return "2 * PI * r";
    case "Square":
      return "4 * s";
    case "Triangle":
      return "a + b + c";
    default:
      // If someone adds a new shape to the union and forgets to handle it,
      // TypeScript throws a compile error here!
      const _exhaustiveCheck: never = shape;
      return _exhaustiveCheck;
  }
}

console.log("Circle formula:", getPerimeterFormula("Circle"));
```

