# Typing `this` in Functions 🧭

You can explicitly declare what `this` must point to by declaring a fake `this` parameter as the **first parameter**:

```typescript
interface Card {
  suit: string;
  rank: number;
}

interface Deck {
  cards: Card[];
  createCardPicker(this: Deck): () => Card;
}

const deck: Deck = {
  cards: [{ suit: "Hearts", rank: 10 }],
  createCardPicker(this: Deck) {
    return () => this.cards[0];
  }
};

const picker = deck.createCardPicker();
console.log("Picked Card:", picker());
```

