# Real-World: Type-Safe API Request Handler 🌐

```typescript
type ApiResponse<T> = {
  status: "success" | "error";
  data?: T;
  errorMessage?: string;
};

function handleApiResponse<T>(response: ApiResponse<T>): void {
  if (response.status === "success" && response.data) {
    console.log("Data loaded successfully:", response.data);
  } else {
    console.error("API error:", response.errorMessage ?? "Unknown error");
  }
}

handleApiResponse<string>({ status: "success", data: "JWT_TOKEN_ABC123" });
handleApiResponse<number[]>({ status: "success", data: [10, 20, 30] });
```

